/**
 * Golden fixtures shared with the Android app (spec/fixtures/*.json).
 *
 * They are generated by the real TypeScript code. `npm run gen:fixtures` rewrites them;
 * a plain test run fails if the committed files are stale. The Android `:core` tests
 * replay the same inputs and must produce the same outputs.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs"
import { resolve } from "node:path"
import { describe, expect, it } from "vitest"

import {
  computeMileageTrend,
  computeOverallStats,
  computeStationStats,
  deriveEntries,
  getOdometerWarning,
  groupByMonth,
} from "@/lib/calculations"
import { parseFuelEntriesCsv } from "@/lib/csv"
import { pipsOf, sectorOf, stationCode } from "@/lib/sector"
import type { FuelEntry } from "@/types/entry"

const FIXTURE_DIR = resolve(__dirname, "../../../spec/fixtures")
const UPDATE = process.env.UPDATE_FIXTURES === "1"

function check(name: string, data: unknown) {
  // Round-trip through JSON so `undefined` and non-finite numbers match what is on disk.
  const json = JSON.stringify(data, null, 2) + "\n"
  const file = resolve(FIXTURE_DIR, `${name}.json`)
  if (UPDATE) {
    mkdirSync(FIXTURE_DIR, { recursive: true })
    writeFileSync(file, json)
    return
  }
  expect(existsSync(file), `${name}.json missing — run npm run gen:fixtures`).toBe(true)
  expect(JSON.parse(json), `${name}.json is stale — run npm run gen:fixtures`).toEqual(
    JSON.parse(readFileSync(file, "utf8"))
  )
}

let seq = 0
function e(
  odometerReading: number,
  litresFilled: number,
  amountPaid: number,
  opts: Partial<Pick<FuelEntry, "isFullTank" | "missedPrevious" | "fuelStation" | "date">> = {}
): FuelEntry {
  seq++
  return {
    id: `e${seq}`,
    vehicleId: "v1",
    date: opts.date ?? `2026-01-${String((seq % 28) + 1).padStart(2, "0")}`,
    odometerReading,
    fuelStation: opts.fuelStation ?? "Indian Oil",
    amountPaid,
    litresFilled,
    isFullTank: opts.isFullTank ?? true,
    missedPrevious: opts.missedPrevious ?? false,
  }
}

/** Small deterministic PRNG (mulberry32) so generated cases are stable. */
function rng(seed: number) {
  let a = seed
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function scenarios(): { name: string; entries: FuelEntry[] }[] {
  const list: { name: string; entries: FuelEntry[] }[] = [
    { name: "empty", entries: [] },
    { name: "single-full", entries: [e(1000, 10, 1000)] },
    { name: "two-full", entries: [e(1000, 10, 1000), e(1400, 8, 820)] },
    {
      name: "partial-in-cycle",
      entries: [e(1000, 10, 1000), e(1200, 4, 410, { isFullTank: false }), e(1500, 6, 620)],
    },
    {
      name: "missed-fill-gap",
      entries: [e(1000, 10, 1000), e(1400, 8, 800, { missedPrevious: true }), e(1800, 9, 900)],
    },
    {
      name: "odometer-regression",
      entries: [e(1000, 10, 1000), e(1500, 8, 800), e(1500, 9, 900), e(2000, 7, 700)],
    },
    {
      name: "partial-first",
      entries: [e(900, 3, 300, { isFullTank: false }), e(1000, 10, 1000), e(1300, 7, 700)],
    },
    { name: "zero-litres", entries: [e(1000, 0, 100), e(1300, 7, 700)] },
    {
      name: "multi-station",
      entries: [
        e(1000, 10, 1000, { fuelStation: "Indian Oil" }),
        e(1300, 7, 720, { fuelStation: "HP" }),
        e(1620, 8, 800, { fuelStation: "Indian Oil" }),
        e(1900, 6, 640, { fuelStation: "Shell · Bandra" }),
        e(2250, 9, 930, { fuelStation: "HP" }),
      ],
    },
    {
      name: "unsorted-input",
      entries: [e(2000, 8, 800), e(1000, 10, 1000), e(1500, 7, 700)],
    },
  ]
  const random = rng(42)
  for (let c = 0; c < 40; c++) {
    const n = 2 + Math.floor(random() * 10)
    let odo = 1000 + Math.floor(random() * 500)
    const entries: FuelEntry[] = []
    for (let i = 0; i < n; i++) {
      const roll = random()
      odo += roll < 0.08 ? -Math.floor(random() * 50) : Math.floor(50 + random() * 400)
      const litres = Math.round((2 + random() * 12) * 100) / 100
      const price = Math.round((90 + random() * 20) * 100) / 100
      entries.push(
        e(odo, litres, Math.round(litres * price * 100) / 100, {
          isFullTank: random() > 0.25,
          missedPrevious: random() < 0.1,
          fuelStation: ["Indian Oil", "HP", "Bharat Petroleum", "Shell"][Math.floor(random() * 4)],
        })
      )
    }
    list.push({ name: `random-${c}`, entries })
  }
  return list
}

describe("golden fixtures", () => {
  it("derive + stats", () => {
    const cases = scenarios().map(({ name, entries }) => {
      const derived = deriveEntries(entries)
      const overall = computeOverallStats(derived)
      return {
        name,
        entries,
        derived,
        overall: {
          ...overall,
          bestMileageEntryId: overall.bestMileageEntry?.id ?? null,
          worstMileageEntryId: overall.worstMileageEntry?.id ?? null,
          bestMileageEntry: undefined,
          worstMileageEntry: undefined,
        },
        stations: computeStationStats(derived),
        trend: computeMileageTrend(derived),
      }
    })
    check("derive", cases)
  })

  it("sector, pips, station code", () => {
    const cases = scenarios()
      .filter((s) => s.entries.length > 0)
      .map(({ name, entries }) => {
        const derived = deriveEntries(entries)
        const overall = computeOverallStats(derived)
        const bestId = overall.bestMileageEntry?.id ?? null
        return {
          name,
          average: overall.averageMileage,
          bestId,
          rows: derived.map((d) => {
            const sector = sectorOf(d, overall.averageMileage, bestId)
            return {
              id: d.id,
              sector,
              pips: d.mileage === null ? null : pipsOf(d.mileage, overall.averageMileage, sector),
            }
          }),
        }
      })
    const names = [
      "Indian Oil",
      "HP",
      "Shell · Bandra",
      "Bharat Petroleum Corp",
      "reliance - nerul",
      "",
      "  ",
      "a b c d",
      "Jio-bp (Thane)",
      "X",
    ]
    check("sector", { cases, stationCodes: names.map((name) => ({ name, code: stationCode(name) })) })
  })

  it("odometer warning", () => {
    const entries = [e(1000, 10, 1000, { date: "2026-01-01" }), e(1500, 8, 800, { date: "2026-01-10" }), e(2500, 9, 900, { date: "2026-02-01" })]
    const probes = [500, 1000, 1200, 1500, 2000, 2500, 2600, 1234567]
    const cases = probes.flatMap((odometer) => [
      { odometer, excludeId: null, warning: getOdometerWarning(entries, odometer) },
      { odometer, excludeId: entries[1].id, warning: getOdometerWarning(entries, odometer, entries[1].id) },
    ])
    check("odometer-warning", { entries, cases })
  })

  it("group by month", () => {
    const rows = [
      { id: "a", date: "2026-03-30" },
      { id: "b", date: "2026-03-02" },
      { id: "c", date: "2026-02-28" },
      { id: "d", date: "2025-03-01" },
    ]
    check("group-by-month", { rows, groups: groupByMonth(rows) })
  })

  it("csv", () => {
    const inputs = [
      "Date,Amount Paid,Odometer Reading,Fuel Filled,Fuel Station\n2026/01/05,500,1000,5,Indian Oil\n",
      "Date,Amount Paid,Odometer Reading,Fuel Filled,Fuel Station,Full Tank,Missed Fill\n05/01/2026,\"1,250.50\",\"12,000\",10.5,\"Shell, Bandra\",no,yes\n",
      "date,amount paid,odometer reading,fuel filled,fuel station\n﻿2026-01-05,₹ 500,1000,5,​HP\n13/01/2026,500,1100,5,HP\n01/13/2026,500,1200,5,HP\n",
      "Date,Amount Paid,Odometer Reading,Fuel Filled,Fuel Station,Full Tank\n2026-01-05,0,1000,5,HP\n2026-01-06,500,1000,5,\nbad,500,1000,5,HP\n2026-01-07,500,1000,5,HP,maybe\n",
      "Date,Amount\n2026-01-05,1\n",
      "",
      "Date,Amount Paid,Odometer Reading,Fuel Filled,Fuel Station\r\n2026-01-05,500,1000,5,\"Say \"\"Hi\"\" Oil\"\r\n\r\n2026-01-06,500,1100,5,HP\r\n",
    ]
    check(
      "csv",
      inputs.map((text) => ({ text, result: parseFuelEntriesCsv(text) }))
    )
  })
})
